import timeimport randomfrom Sengo1 import *from mpython import *from machine import UARTuart1 = UART(1, baudrate=115200, tx=Pin.P14, rx=Pin.P13)sengo1 = Sengo1(0x60)random.seed(time.ticks_cpu())# 自定义函数def UART():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, param_set, index, random  sengo1.begin(uart1)def I2C():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, param_set, index, random  sengo1.begin(i2c)def Param_Set():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, param_set, index, random  if (param_set == 1):    oled.fill_rect(0, (2-1)*16, 128, 16, 0)    oled.show()    if (key_A == 1):      key_A = 0      index = (random.randint(1, 6))    if (key_B == 1):      key_B = 0      index = (index + 1)      if (index == 7):        index = 1    oled.DispChar((str(index)), 112, 0, 1)    oled.show()    if (index == 1):      sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 6, 6, color_label_e.kColorBlack], 1)      # 等待新参数生效后的识别结果产出，该时间间隔不得低于该算法识别1帧所花费的时间，可以通过算法开启后，屏幕下方的帧率进行推算      time.sleep(0.1)    if (index == 2):      sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 6, 6, color_label_e.kColorWhite], 1)      time.sleep(0.1)    if (index == 3):      sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 6, 8, color_label_e.kColorRed], 1)      time.sleep(0.1)    if (index == 4):      sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 8, 6, color_label_e.kColorGreen], 1)      time.sleep(0.1)    if (index == 5):      sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 8, 8, color_label_e.kColorBlue], 1)      time.sleep(0.1)    if (index == 6):      sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 8, 6, color_label_e.kColorYellow], 1)      time.sleep(0.1)    oled.DispChar("Operation OK!", 0, (2-1)*16, 1)    oled.show()    time.sleep(0.2)    oled.fill_rect(0, (2-1)*16, 128, 16, 0)    param_set = 0def Display():  global my_variable, key_N, key_P, key_T, key_H, key_A, key_B, param_set, index, random  if (param_set == 0):    oled.fill_rect(0, (2-1)*16, 128, 16, 0)    oled.show()    # Sengo1不主动返回检测识别结果，需要主控板发送指令进行读取。读取的流程：首先读取识别结果的数量，接收到指令后，Sengo1会刷新结果数据，如果结果数量不为零，那么主控再发送指令读取结果的相关信息。请务必按此流程构建程序。    # Sengo最多输出1个识别结果。    if ((sengo1.GetValue(sengo1_vision_e.kVisionBlob, sentry_obj_info_e.kStatus)) > 0):      if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorBlack):        oled.DispChar("Black", 0, (2-1)*16, 1)      if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorWhite):        oled.DispChar("White", 0, (2-1)*16, 1)      if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorRed):        oled.DispChar("Red", 0, (2-1)*16, 1)      if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorGreen):        oled.DispChar("Green", 0, (2-1)*16, 1)      if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorBlue):        oled.DispChar("Blue", 0, (2-1)*16, 1)      if (sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kLabel)==color_label_e.kColorYellow):        oled.DispChar("Yellow", 0, (2-1)*16, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kXValue)))), 32, 32, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kYValue)))), 96, 32, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kWidthValue)))), 32, 48, 1)      oled.DispChar((str((sengo1.GetValue(sengo1_vision_e.kVisionBlob,sentry_obj_info_e.kHeightValue)))), 96, 48, 1)    else:      oled.fill_rect(32,32,32,16,0)      oled.fill_rect(96,32,32,16,0)      oled.fill_rect(32,48,32,16,0)      oled.fill_rect(96,48,32,16,0)    oled.show()# 事件回调函数def on_button_a_down(_):  time.sleep_ms(10)  if button_a.value() == 1: return  global param_set  global key_A  param_set = 1  key_A = 1def on_button_b_down(_):  time.sleep_ms(10)  if button_b.value() == 1: return  global param_set  global key_B  param_set = 1  key_B = 1button_a.irq(trigger=Pin.IRQ_FALLING, handler=on_button_a_down)button_b.irq(trigger=Pin.IRQ_FALLING, handler=on_button_b_down)index = 0key_A = 0key_B = 0param_set = 0# 等待Sengo1完成初始化，此延时不可以去掉，避免Sengo1初始化尚未完成，主控板已经发送指令time.sleep(2)I2C()# 1、算法的默认设置，如果无需更改参数，则可移除本代码块；# 2、只有色块检测与颜色识别算法需要设置参数；# 3、合理设置最小宽度与最小高度值，可以过滤背景的干扰区域sengo1.SetParam(sengo1_vision_e.kVisionBlob,[0, 0, 3, 4, color_label_e.kColorRed], 1)# 1、参考文档# https://tosee.readthedocs.io/zh/latest/Sentry1/Vision/index.html#chapter-vs1-vision-blob-index# 2、参考视频（注：Sengo1与Sentry1是两款产品）# https://www.bilibili.com/video/BV1924y157UD/?spm_id_from=333.1387.upload.video_card.click&vd_source=a6a4a13d17ed26ee248472534a8ec3cc# 3、色块检测算法常见的应用场景：分拣与搬运不同颜色的物体；巡线，包括常见的白底黑线地图以及模拟道路的地图# 4、Sengo1每次只能运行一种识别算法# 5、正常使用时，应由主控板发送指令控制Sengo1的算法开启关闭，而不是通过Sengo1的摇杆进行操作；sengo1.VisionBegin(sengo1_vision_e.kVisionBlob)oled.DispChar("Algo: Blob", 0, 0, 1)oled.DispChar("index: ", 64, 0, 1)oled.DispChar((str(index)), 112, 0, 1)oled.DispChar("x=", 0, 32, 1)oled.DispChar("y=", 64, 32, 1)oled.DispChar("w=", 0, 48, 1)oled.DispChar("h=", 64, 48, 1)oled.show()while True:  Param_Set()  Display()